import{_ as e,c as r,o as t,ah as i}from"./chunks/framework.5ZZXabC7.js";const b=JSON.parse('{"title":"학습 노트","description":"","frontmatter":{},"headers":[],"relativePath":"study/index.md","filePath":"study/index.md","lastUpdated":1756890187000}'),l={name:"study/index.md"};function o(n,a,h,s,d,c){return t(),r("div",null,[...a[0]||(a[0]=[i('<h1 id="학습-노트" tabindex="-1">학습 노트 <a class="header-anchor" href="#학습-노트" aria-label="Permalink to “학습 노트”">​</a></h1><blockquote><p>&quot;오늘 배운 건 내일 까먹기 전에 정리하자!&quot;</p></blockquote><p>개발하면서 배운 것들을 일기처럼 편하게 정리하는 공간입니다.<br> 실수한 것도, 헤맨 것도, 드디어 해결한 것도 다 기록해요. 나중에 다시 보면서 &quot;아 맞다, 이땐 이런 문제가 있었지&quot; 하고 기억나게 하려고요.</p><h2 id="작성된-학습-노트" tabindex="-1">작성된 학습 노트 <a class="header-anchor" href="#작성된-학습-노트" aria-label="Permalink to “작성된 학습 노트”">​</a></h2><h3 id="javascript" tabindex="-1">JavaScript <a class="header-anchor" href="#javascript" aria-label="Permalink to “JavaScript”">​</a></h3><ul><li><strong><a href="./javascript-es6-features.html">JavaScript ES6+ 핵심 정리</a></strong> - 모던 JS 문법 정리</li></ul><h3 id="곧-추가될-노트들" tabindex="-1">곧 추가될 노트들 <a class="header-anchor" href="#곧-추가될-노트들" aria-label="Permalink to “곧 추가될 노트들”">​</a></h3><ul><li><strong>TypeScript 기초</strong> - 타입 시스템 이해하기</li><li><strong>React Hooks 패턴</strong> - 실무에서 자주 쓰는 패턴들</li><li><strong>Git 협업</strong> - 브랜치 전략과 PR 작성법</li><li><strong>Tailwind CSS</strong> - 유틸리티 클래스 활용법</li></ul><hr><h2 id="나는-이렇게-공부해요" tabindex="-1">나는 이렇게 공부해요 <a class="header-anchor" href="#나는-이렇게-공부해요" aria-label="Permalink to “나는 이렇게 공부해요”">​</a></h2><h3 id="_1-일단-해보기" tabindex="-1">1. 일단 해보기 <a class="header-anchor" href="#_1-일단-해보기" aria-label="Permalink to “1. 일단 해보기”">​</a></h3><p>새로운 걸 배울 때 문서 읽기보다는 예제부터 따라해봐요.<br> &quot;이게 뭔지는 모르겠지만 일단 해보자!&quot; 하면서 시작하는 편이에요. 그래야 감이 와요.</p><h3 id="_2-막히면-바로-구글링" tabindex="-1">2. 막히면 바로 구글링 <a class="header-anchor" href="#_2-막히면-바로-구글링" aria-label="Permalink to “2. 막히면 바로 구글링”">​</a></h3><p>뭔가 안 되면 바로 구글에 검색해봐요.<br> &quot;왜 이렇게 되지?&quot; 하면서 계속 파고들다 보면 어느새 이해가 되더라고요.</p><h3 id="_3-내-말로-다시-정리하기" tabindex="-1">3. 내 말로 다시 정리하기 <a class="header-anchor" href="#_3-내-말로-다시-정리하기" aria-label="Permalink to “3. 내 말로 다시 정리하기”">​</a></h3><p>공식 문서는 너무 딱딱해서 나중에 다시 봐도 이해가 안 돼요.<br> 그래서 내가 이해한 방식으로 다시 써놓는 편이에요. &quot;아 이거 그냥 이런 거구나!&quot; 식으로요.</p><h3 id="_4-바로-써먹어보기" tabindex="-1">4. 바로 써먹어보기 <a class="header-anchor" href="#_4-바로-써먹어보기" aria-label="Permalink to “4. 바로 써먹어보기”">​</a></h3><p>배운 건 바로 뭔가 만들어보면서 써봐요.<br> 실제로 쓰면서 &quot;아 이럴 때 이렇게 하는구나&quot; 하고 체득하는 게 가장 확실한 것 같아요.</p><h2 id="최근에-관심-있는-주제들" tabindex="-1">최근에 관심 있는 주제들 <a class="header-anchor" href="#최근에-관심-있는-주제들" aria-label="Permalink to “최근에 관심 있는 주제들”">​</a></h2><h3 id="next-js" tabindex="-1">Next.js <a class="header-anchor" href="#next-js" aria-label="Permalink to “Next.js”">​</a></h3><p>React를 어느 정도 익혔으니 이제 Next.js를 배워보고 싶어요.<br> SSR, API Routes 등 풀스택 개발에도 도전해보고 싶습니다.</p><h3 id="성능-최적화" tabindex="-1">성능 최적화 <a class="header-anchor" href="#성능-최적화" aria-label="Permalink to “성능 최적화”">​</a></h3><p>사용자가 체감할 수 있는 성능 개선에 관심이 많아졌어요.<br> 번들 사이즈 줄이기, 이미지 최적화, 로딩 시간 단축 등등.</p><h3 id="테스트-코드" tabindex="-1">테스트 코드 <a class="header-anchor" href="#테스트-코드" aria-label="Permalink to “테스트 코드”">​</a></h3><p>지금까지는 브라우저에서 직접 테스트하는 방식이었는데,<br> 자동화된 테스트 코드 작성법을 배우고 싶습니다.</p><hr><p><strong>새로운 학습 노트가 계속 추가될 예정이니, 종종 들러주세요!</strong></p>',27)])])}const _=e(l,[["render",o]]);export{b as __pageData,_ as default};
